def refund_error(reason, retryable, category):
    payload = {
        "errorCategory": category,   # transient | validation | business | permission
        "isRetryable": retryable,
        "message": reason,
    }
    return {"content": [{"type": "text", "text": json.dumps(payload)}],
            "isError": True}

# Business rule, not a glitch: retrying will not help
return refund_error("Order is past the 30-day refund window. Offer store credit or escalate.",
                    False, "business")

